arguments.new_str:
namespace Warehouse;

public sealed class InventoryTracker
{
    private readonly Dictionary<string, Dictionary<string, int>> _warehouseStock = new();
    private readonly int _reorderThreshold;

    public InventoryTracker(int reorderThreshold = 10)
    {
        if (reorderThreshold < 0)
            throw new ArgumentOutOfRangeException(nameof(reorderThreshold));
        _reorderThreshold = reorderThreshold;
    }

    public int GetStockLevel(string sku)
    {
        ArgumentNullException.ThrowIfNull(sku);
        int total = 0;
        foreach (var warehouse in _warehouseStock.Values)
            if (warehouse.TryGetValue(sku, out int qty))
                total += qty;
        return total;
    }

    public int GetStockLevel(string sku, string warehouse)
    {
        ArgumentNullException.ThrowIfNull(sku);
        ArgumentNullException.ThrowIfNull(warehouse);
        if (_warehouseStock.TryGetValue(warehouse, out var stock) &&
            stock.TryGetValue(sku, out int qty))
            return qty;
        return 0;
    }

    public void AddStock(string sku, int quantity, string warehouse = "default")
    {
        ArgumentNullException.ThrowIfNull(sku);
        ArgumentNullException.ThrowIfNull(warehouse);
        if (quantity <= 0)
            throw new ArgumentOutOfRangeException(nameof(quantity));

        if (!_warehouseStock.TryGetValue(warehouse, out var stock))
        {
            stock = new Dictionary<string, int>();
            _warehouseStock[warehouse] = stock;
        }

        stock.TryGetValue(sku, out int current);
        stock[sku] = current + quantity;
    }

    public bool NeedsReorder(string sku)
    {
        ArgumentNullException.ThrowIfNull(sku);
        return GetStockLevel(sku) <= _reorderThreshold;
    }

    public void TransferStock(string sku, int quantity, string fromWarehouse, string toWarehouse)
    {
        ArgumentNullException.ThrowIfNull(sku);
        ArgumentNullException.ThrowIfNull(fromWarehouse);
        ArgumentNullException.ThrowIfNull(toWarehouse);
        if (quantity <= 0)
            throw new ArgumentOutOfRangeException(nameof(quantity));
        if (fromWarehouse == toWarehouse)
            throw new ArgumentException("Source and destination warehouses must differ.", nameof(toWarehouse));

        if (!_warehouseStock.TryGetValue(fromWarehouse, out var fromStock) ||
            !fromStock.TryGetValue(sku, out int available) ||
            available < quantity)
        {
            throw new InvalidOperationException(
                $"Insufficient stock of '{sku}' in warehouse '{fromWarehouse}'.");
        }

        fromStock[sku] = available - quantity;

        if (!_warehouseStock.TryGetValue(toWarehouse, out var toStock))
        {
            toStock = new Dictionary<string, int>();
            _warehouseStock[toWarehouse] = toStock;
        }

        toStock.TryGetValue(sku, out int current);
        toStock[sku] = current + quantity;
    }
}

