using Warehouse;

namespace Warehouse.Tests;

[TestClass]
public class InventoryTrackerTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup() => _tracker = new InventoryTracker(reorderThreshold: 5);

    // ── Construction ───────────────────────────────────────────────

    [TestMethod]
    public void Constructor_DefaultThreshold_DoesNotThrow()
    {
        var tracker = new InventoryTracker();
        Assert.IsNotNull(tracker);
    }

    [TestMethod]
    public void Constructor_NegativeThreshold_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => new InventoryTracker(reorderThreshold: -1));
    }

    [TestMethod]
    public void Constructor_ZeroThreshold_IsAllowed()
    {
        var tracker = new InventoryTracker(reorderThreshold: 0);
        tracker.AddStock("SKU-1", 1);
        Assert.IsFalse(tracker.NeedsReorder("SKU-1"));
    }

    // ── AddStock ───────────────────────────────────────────────────

    [TestMethod]
    public void AddStock_SingleItem_IncreasesStockLevel()
    {
        _tracker.AddStock("SKU-A", 20);
        Assert.AreEqual(20, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void AddStock_MultipleCalls_Accumulates()
    {
        _tracker.AddStock("SKU-A", 10);
        _tracker.AddStock("SKU-A", 5);
        Assert.AreEqual(15, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void AddStock_DifferentSkus_TrackedIndependently()
    {
        _tracker.AddStock("SKU-A", 10);
        _tracker.AddStock("SKU-B", 3);
        Assert.AreEqual(10, _tracker.GetStockLevel("SKU-A"));
        Assert.AreEqual(3, _tracker.GetStockLevel("SKU-B"));
    }

    [TestMethod]
    public void AddStock_ZeroQuantity_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.AddStock("SKU-A", 0));
    }

    [TestMethod]
    public void AddStock_NegativeQuantity_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.AddStock("SKU-A", -5));
    }

    [TestMethod]
    public void AddStock_NullSku_Throws()
    {
        Assert.ThrowsException<ArgumentNullException>(
            () => _tracker.AddStock(null!, 1));
    }

    [TestMethod]
    public void AddStock_ToSpecificWarehouse_TrackedSeparately()
    {
        _tracker.AddStock("SKU-A", 10, "WH-East");
        _tracker.AddStock("SKU-A", 7, "WH-West");
        Assert.AreEqual(10, _tracker.GetStockLevel("SKU-A", "WH-East"));
        Assert.AreEqual(7, _tracker.GetStockLevel("SKU-A", "WH-West"));
        Assert.AreEqual(17, _tracker.GetStockLevel("SKU-A"));
    }

    // ── GetStockLevel ──────────────────────────────────────────────

    [TestMethod]
    public void GetStockLevel_UnknownSku_ReturnsZero()
    {
        Assert.AreEqual(0, _tracker.GetStockLevel("UNKNOWN"));
    }

    [TestMethod]
    public void GetStockLevel_NullSku_Throws()
    {
        Assert.ThrowsException<ArgumentNullException>(
            () => _tracker.GetStockLevel(null!));
    }

    [TestMethod]
    public void GetStockLevel_ByWarehouse_UnknownWarehouse_ReturnsZero()
    {
        _tracker.AddStock("SKU-A", 10, "WH-East");
        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-A", "WH-Unknown"));
    }

    [TestMethod]
    public void GetStockLevel_AggregatesAcrossWarehouses()
    {
        _tracker.AddStock("SKU-A", 3, "WH-1");
        _tracker.AddStock("SKU-A", 4, "WH-2");
        _tracker.AddStock("SKU-A", 5, "WH-3");
        Assert.AreEqual(12, _tracker.GetStockLevel("SKU-A"));
    }

    // ── NeedsReorder ───────────────────────────────────────────────

    [TestMethod]
    public void NeedsReorder_StockBelowThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-A", 3);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_StockAtThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-A", 5); // threshold is 5
        Assert.IsTrue(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_StockAboveThreshold_ReturnsFalse()
    {
        _tracker.AddStock("SKU-A", 6);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_UnknownSku_ReturnsTrue()
    {
        Assert.IsTrue(_tracker.NeedsReorder("NEVER-STOCKED"));
    }

    [TestMethod]
    public void NeedsReorder_NullSku_Throws()
    {
        Assert.ThrowsException<ArgumentNullException>(
            () => _tracker.NeedsReorder(null!));
    }

    [TestMethod]
    public void NeedsReorder_ConsidersAllWarehouses()
    {
        _tracker.AddStock("SKU-A", 3, "WH-East");
        _tracker.AddStock("SKU-A", 3, "WH-West");
        // total = 6, above threshold 5
        Assert.IsFalse(_tracker.NeedsReorder("SKU-A"));
    }

    // ── TransferStock ──────────────────────────────────────────────

    [TestMethod]
    public void TransferStock_MovesQuantityBetweenWarehouses()
    {
        _tracker.AddStock("SKU-A", 20, "WH-East");
        _tracker.TransferStock("SKU-A", 8, "WH-East", "WH-West");

        Assert.AreEqual(12, _tracker.GetStockLevel("SKU-A", "WH-East"));
        Assert.AreEqual(8, _tracker.GetStockLevel("SKU-A", "WH-West"));
    }

    [TestMethod]
    public void TransferStock_TotalStockUnchanged()
    {
        _tracker.AddStock("SKU-A", 20, "WH-East");
        _tracker.TransferStock("SKU-A", 8, "WH-East", "WH-West");
        Assert.AreEqual(20, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void TransferStock_EntireStock_LeavesZeroInSource()
    {
        _tracker.AddStock("SKU-A", 10, "WH-East");
        _tracker.TransferStock("SKU-A", 10, "WH-East", "WH-West");

        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-A", "WH-East"));
        Assert.AreEqual(10, _tracker.GetStockLevel("SKU-A", "WH-West"));
    }

    [TestMethod]
    public void TransferStock_InsufficientStock_Throws()
    {
        _tracker.AddStock("SKU-A", 5, "WH-East");
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.TransferStock("SKU-A", 10, "WH-East", "WH-West"));
    }

    [TestMethod]
    public void TransferStock_UnknownSourceWarehouse_Throws()
    {
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.TransferStock("SKU-A", 1, "NO-SUCH-WH", "WH-West"));
    }

    [TestMethod]
    public void TransferStock_SameWarehouse_Throws()
    {
        _tracker.AddStock("SKU-A", 10, "WH-East");
        Assert.ThrowsException<ArgumentException>(
            () => _tracker.TransferStock("SKU-A", 5, "WH-East", "WH-East"));
    }

    [TestMethod]
    public void TransferStock_ZeroQuantity_Throws()
    {
        _tracker.AddStock("SKU-A", 10, "WH-East");
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.TransferStock("SKU-A", 0, "WH-East", "WH-West"));
    }

    [TestMethod]
    public void TransferStock_NegativeQuantity_Throws()
    {
        _tracker.AddStock("SKU-A", 10, "WH-East");
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.TransferStock("SKU-A", -3, "WH-East", "WH-West"));
    }

    [TestMethod]
    public void TransferStock_NullSku_Throws()
    {
        Assert.ThrowsException<ArgumentNullException>(
            () => _tracker.TransferStock(null!, 1, "WH-East", "WH-West"));
    }

    [TestMethod]
    public void TransferStock_NullFromWarehouse_Throws()
    {
        Assert.ThrowsException<ArgumentNullException>(
            () => _tracker.TransferStock("SKU-A", 1, null!, "WH-West"));
    }

    [TestMethod]
    public void TransferStock_NullToWarehouse_Throws()
    {
        Assert.ThrowsException<ArgumentNullException>(
            () => _tracker.TransferStock("SKU-A", 1, "WH-East", null!));
    }

    [TestMethod]
    public void TransferStock_ToExistingWarehouse_Accumulates()
    {
        _tracker.AddStock("SKU-A", 10, "WH-East");
        _tracker.AddStock("SKU-A", 5, "WH-West");
        _tracker.TransferStock("SKU-A", 3, "WH-East", "WH-West");

        Assert.AreEqual(7, _tracker.GetStockLevel("SKU-A", "WH-East"));
        Assert.AreEqual(8, _tracker.GetStockLevel("SKU-A", "WH-West"));
    }

    // ── Reorder after Transfer ─────────────────────────────────────

    [TestMethod]
    public void NeedsReorder_AfterTransferReducesTotal_ReturnsTrue()
    {
        // Total starts at 6 (above threshold 5)
        _tracker.AddStock("SKU-A", 6, "WH-East");
        Assert.IsFalse(_tracker.NeedsReorder("SKU-A"));

        // Transfer doesn't change total, still 6
        _tracker.TransferStock("SKU-A", 3, "WH-East", "WH-West");
        Assert.IsFalse(_tracker.NeedsReorder("SKU-A"));
    }
}

